insert into public.mg628_lab_questions (lab, id, module, kind, body) values
  ('forecasting','m1q1','m1','static',$q${"stem": "What distinguishes time series data from cross-sectional data?", "opts": ["It always has more rows", "The order and spacing of observations matter", "It has no missing values", "It contains only one variable"], "ans": 1, "why": "Shuffling a time series destroys its information; shuffling a survey does not."}$q$::jsonb),
  ('forecasting','m1q2','m1','static',$q${"stem": "Recessions and recoveries that last several years with no fixed length are best described as:", "opts": ["Seasonality", "Cycles", "Irregular variation", "Stationarity"], "ans": 1, "why": "Cycles are long swings without a fixed period."}$q$::jsonb),
  ('forecasting','m1q3','m1','static',$q${"stem": "Why do analysts difference a series before fitting ARIMA?", "opts": ["To remove outliers", "To make it stationary", "To add seasonality", "To shorten the series"], "ans": 1, "why": "ARIMA assumes stationarity; differencing removes trend or seasonal level changes."}$q$::jsonb),
  ('forecasting','m1q4','m1','static',$q${"stem": "SHEIN's monthly sales have an ADF test p-value of 0.999. What does that suggest?", "opts": ["The series is stationary", "The series is non-stationary", "The series has no trend", "The data are random"], "ans": 1, "why": "A high p-value means we cannot reject a unit root: the series is non-stationary."}$q$::jsonb),
  ('forecasting','m1q5','m1','static',$q${"stem": "Which is an example of irregular variation?", "opts": ["Higher sales every December", "Steady population growth", "A one-day spike from a viral social media post", "Lower water use every winter"], "ans": 2, "why": "A one-off shock that doesn't repeat is irregular variation."}$q$::jsonb),
  ('forecasting','m1q6','m1','static',$q${"stem": "What makes forecasting a time series possible in the first place?", "opts": ["Observations are independent", "Values are related to their own past (autocorrelation)", "Every series is stationary", "Seasonality is always absent"], "ans": 1, "why": "Dependence on the past is what lets history inform the future."}$q$::jsonb),
  ('forecasting','m2q1','m2','static',$q${"stem": "Why average the available 4-hour periods instead of summing them each month?", "opts": ["Averages are always larger", "Sums understate months with more missing periods", "Sums can't be plotted", "Averages remove seasonality"], "ans": 1, "why": "Missing periods lower a sum but not an average of the available ones."}$q$::jsonb),
  ('forecasting','m2q2','m2','static',$q${"stem": "Macy's autocorrelation is 0.44 at lag 1 and 0.69 at lag 12. What does this suggest?", "opts": ["No seasonality", "Strong yearly seasonality", "A data error", "The series is stationary"], "ans": 1, "why": "The same month last year predicts better than last month: yearly seasonality."}$q$::jsonb),
  ('forecasting','m2q3','m2','static',$q${"stem": "SHEIN sells about 6,550 per period at weekends and 5,670 on weekdays. The weekend effect is about:", "opts": ["+5%", "+16%", "+50%", "−16%"], "ans": 1, "why": "6,550 ÷ 5,670 ≈ 1.16."}$q$::jsonb),
  ('forecasting','m2q4','m2','static',$q${"stem": "What is the first step before fitting any forecasting model?", "opts": ["Compute MAPE", "Plot the series over time", "Fit SARIMA", "Remove all outliers"], "ans": 1, "why": "Plots reveal trend, seasonality and oddities before modeling."}$q$::jsonb),
  ('forecasting','m2q5','m2','static',$q${"stem": "In an additive model, a December effect of +2,000 means:", "opts": ["December adds about 2,000 units whatever the level", "December adds 2,000%", "December doubles sales", "December is 2,000 below trend"], "ans": 0, "why": "Additive effects are fixed amounts in the series' units."}$q$::jsonb),
  ('forecasting','m2q6','m2','static',$q${"stem": "January's seasonal index is 0.73. Relative to trend, January sales are about:", "opts": ["27% below", "73% below", "27% above", "Equal to trend"], "ans": 0, "why": "0.73 means 27% below trend."}$q$::jsonb),
  ('forecasting','m3q1','m3','static',$q${"stem": "Why does a 12-month window remove seasonality from monthly data?", "opts": ["It drops December", "Each average contains one of every month", "It uses only recent data", "It fits a straight line"], "ans": 1, "why": "Every window spans a full seasonal cycle, so the swings cancel."}$q$::jsonb),
  ('forecasting','m3q2','m3','static',$q${"stem": "Macy's regression has R² = 0.13. The best conclusion is:", "opts": ["There is no trend", "The line explains little month-to-month variation, but a trend can still be real", "The data are wrong", "Use a 3-month average instead"], "ans": 1, "why": "Seasonal swings dominate variance; the moving average confirms the decline."}$q$::jsonb),
  ('forecasting','m3q3','m3','static',$q${"stem": "Which method gives an equation that can be extended into future months?", "opts": ["12-month moving average", "Linear regression on time", "Seasonal index", "Autocorrelation"], "ans": 1, "why": "Regression gives Y = a + b × t, which can be extrapolated."}$q$::jsonb),
  ('forecasting','m3q4','m3','static',$q${"stem": "A key weakness of a trailing moving average is that it:", "opts": ["Can't remove seasonality", "Lags behind turning points", "Requires an equation", "Is always non-stationary"], "ans": 1, "why": "It averages past values, so it reacts late to changes."}$q$::jsonb),
  ('forecasting','m3q5','m3','static',$q${"stem": "The moving average bends upward sharply while the regression line is straight. What does that suggest?", "opts": ["The straight line is a fair summary", "The straight line misleads about the trend's shape", "R² must be 1", "Seasonality is absent"], "ans": 1, "why": "A bending moving average signals a non-linear trend the line can't capture."}$q$::jsonb),
  ('forecasting','m3q6','m3','static',$q${"stem": "Which choice of window best removes a weekly cycle from daily data?", "opts": ["3 days", "7 days", "12 days", "30 days"], "ans": 1, "why": "Match the window to the season length: 7 for a weekly cycle in daily data."}$q$::jsonb),
  ('forecasting','m4q1','m4','static',$q${"stem": "Why compare every model with a seasonal naive forecast?", "opts": ["It is always the best", "It sets a cheap bar a useful model must beat", "It removes trend", "It is required by statsmodels"], "ans": 1, "why": "If a complex model can't beat the seasonal naive, it isn't worth it."}$q$::jsonb),
  ('forecasting','m4q2','m4','static',$q${"stem": "Simple exponential smoothing forecasts for strongly seasonal data are poor because they:", "opts": ["Use too much data", "Produce a flat forecast with no trend or season", "Need stationarity", "Overfit seasonality"], "ans": 1, "why": "SES forecasts one level for every future period."}$q$::jsonb),
  ('forecasting','m4q3','m4','static',$q${"stem": "In ARIMA, the 'I' (integrated) step:", "opts": ["Adds seasonality", "Differences the series to make it stationary", "Uses past errors", "Averages recent values"], "ans": 1, "why": "Differencing handles the trend."}$q$::jsonb),
  ('forecasting','m4q4','m4','static',$q${"stem": "The 'MA' in ARIMA refers to:", "opts": ["A moving-average smoother", "Past forecast errors", "Monthly averages", "Mean absolute error"], "ans": 1, "why": "ARIMA's MA terms model past forecast errors, not a smoother."}$q$::jsonb),
  ('forecasting','m4q5','m4','static',$q${"stem": "Why did SARIMA do worse on SHEIN than on Macy's here?", "opts": ["SARIMA can't model trends", "Only 48 training months and strong growth gave it little to learn from", "SHEIN has no seasonality", "It was given test data"], "ans": 1, "why": "Short histories limit seasonal ARIMA, and SHEIN's growth makes it harder."}$q$::jsonb),
  ('forecasting','m4q6','m4','static',$q${"stem": "A machine learning forecast using lag-1 and lag-12 features is most appropriate when:", "opts": ["You have only 24 monthly values", "You have long, detailed histories and many drivers", "You need the simplest model", "The data are cross-sectional"], "ans": 1, "why": "ML needs much more data and pays off with many drivers."}$q$::jsonb),
  ('forecasting','m5q1','m5','static',$q${"stem": "Why must the test period come after the training period?", "opts": ["It is faster", "Otherwise the model learns from the future and accuracy looks too good", "MAPE requires it", "It removes seasonality"], "ans": 1, "why": "A random split leaks future information."}$q$::jsonb),
  ('forecasting','m5q2','m5','static',$q${"stem": "Compared with MAE, RMSE:", "opts": ["Ignores big misses", "Penalizes big misses more heavily", "Is unit-free", "Is always smaller"], "ans": 1, "why": "Squaring the errors weights large misses more."}$q$::jsonb),
  ('forecasting','m5q3','m5','static',$q${"stem": "When is MAPE unreliable?", "opts": ["When actual values are near zero", "When there are 12 test months", "When errors are positive", "When data are monthly"], "ans": 0, "why": "Dividing by values near zero inflates percentages."}$q$::jsonb),
  ('forecasting','m5q4','m5','static',$q${"stem": "A 95% prediction interval widens over the 12 forecast months because:", "opts": ["The model gets worse data", "Uncertainty grows the further ahead you forecast", "Seasonality disappears", "MAPE increases"], "ans": 1, "why": "Each step ahead adds uncertainty."}$q$::jsonb),
  ('forecasting','m5q5','m5','static',$q${"stem": "If running out of stock in December is very costly, plan inventory toward:", "opts": ["The lower end of the interval", "The upper end of the interval", "The naive forecast", "Last year's January"], "ans": 1, "why": "Costly shortfalls argue for planning toward the upper end."}$q$::jsonb),
  ('forecasting','m5q6','m5','static',$q${"stem": "Holt-Winters' 2025 MAE for SHEIN was about $276 per period. That number is most useful for:", "opts": ["Comparing with Macy's", "Planning in real units, such as stock or staffing", "Testing stationarity", "Choosing the seasonal period"], "ans": 1, "why": "MAE is in real units, so it translates directly into plans."}$q$::jsonb),
  ('forecasting','m6q1','m6','static',$q${"stem": "What is the first rung of the model-choice ladder?", "opts": ["SARIMA", "Naive and seasonal naive baselines", "LSTM", "Holt-Winters"], "ans": 1, "why": "Baselines are cheap and set the bar for everything else."}$q$::jsonb),
  ('forecasting','m6q2','m6','static',$q${"stem": "Which statsmodels class produces seasonal ARIMA forecasts with prediction intervals?", "opts": ["seasonal_decompose", "SARIMAX", "LinearRegression", "rolling"], "ans": 1, "why": "SARIMAX fits seasonal ARIMA and returns intervals via get_forecast."}$q$::jsonb),
  ('forecasting','m6q3','m6','static',$q${"stem": "A colleague says 'R² is 0.95, so this is a great forecast.' The best response is:", "opts": ["Agree", "R² measures fit to the past; test on a later period", "R² should be 1", "Use MAPE on training data"], "ans": 1, "why": "Only held-out performance measures forecasting skill."}$q$::jsonb),
  ('forecasting','m6q4','m6','static',$q${"stem": "Why include a trigger in a forecast statement?", "opts": ["To look more precise", "So everyone knows when the plan will be revisited", "To replace the range", "It is required by pandas"], "ans": 1, "why": "A trigger defines when evidence will force a re-plan."}$q$::jsonb),
  ('forecasting','m6q5','m6','static',$q${"stem": "Holt-Winters is often the best value for monthly business data with steady growth and a stable season because it is:", "opts": ["The most complex model", "Accurate, fast and easy to explain", "Free of assumptions", "A machine learning model"], "ans": 1, "why": "It fits that structure well and is easy to communicate."}$q$::jsonb),
  ('forecasting','m6q6','m6','static',$q${"stem": "Which statement is a misconception?", "opts": ["A forecast should include a range", "A moving average on its own forecasts future turning points", "Test on a later period", "Compare with baselines"], "ans": 1, "why": "A moving average describes the past; extended alone it gives a flat forecast."}$q$::jsonb);
